def is_profile_admitted_for_selection(profile_name, *, source=""):
    if profile_name in _UNSAFE_DIAGNOSTIC_PROFILES:
        if os.environ.get("RIG_RELAY_ALLOW_UNSAFE", "") != "1":
            return False, "Profile '{profile_name}' is a diagnostic-only mode..."
    return True, None
